public class CalculateShippingFeeAcceptanceTests
{
    private static int Fee(string total, string tier, bool express) =>
        new CalculateShippingFee().Handle(
            new CalculateShippingFeeQuery(Money.Cents(total), Money.Tier(tier), express));

    // Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData("49.99", "Bronze", "4.90")]
    [InlineData("50.00", "Bronze", "0.00")]
    [InlineData("49.99", "Silver", "4.90")]
    public void S11_StandardShippingIsFreeFromFiftyEuros(string total, string tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier, false));

    // Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData("Gold")]
    [InlineData("Platinum")]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(string tier) =>
        Assert.Equal(Money.Cents("0.00"), Fee("10.00", tier, false));

    // Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData("100.00", "Bronze", "9.90")]
    [InlineData("10.00", "Gold", "9.90")]
    [InlineData("10.00", "Platinum", "0.00")]
    public void S13_ExpressShippingCostsNinePointNinety(string total, string tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier, true));
}

